import cv2,numpy as np
im=cv2.imread('first_frame.png')
for m in ['bilateral','median','gaussian']:
 if m=='bilateral': out=cv2.bilateralFilter(im,9,40,40)
 elif m=='median': out=cv2.medianBlur(im,5)
 else: out=cv2.GaussianBlur(im,(5,5),0)
 cv2.imwrite(f'.tmp/{m}.png',out)
# print quantized luminance maps 128x72 every 4 rows to inspect large forms
im=np.asarray(cv2.cvtColor(cv2.imread('first_frame.png'),cv2.COLOR_BGR2RGB)).astype(float)
lum=im@[.299,.587,.114]
chars=' .:-=+*#%@'
for y in range(0,144,4):
 print(''.join(chars[min(9,int(lum[y:y+4,x:x+2].mean()/256*10))] for x in range(0,256,2)))
